using System.Buffers.Binary;

namespace Lintel.Primitives;

/// <summary>
/// Default implementation of <see cref="ISequentialGuidProvider"/>: takes a random GUID and replaces
/// 6 of its bytes with the number of milliseconds since the Unix epoch.
/// </summary>
/// <remarks>
/// The byte layout is identical to <c>Structr.Abstractions</c> <c>SequentialGuidProvider</c>, so new keys keep
/// sorting after keys generated by Structr.
/// </remarks>
public class SequentialGuidProvider : ISequentialGuidProvider
{
    private static readonly long _unixEpochTicks = DateTime.UnixEpoch.Ticks;

    private readonly SequentialGuidInitializer _initializer;
    private readonly SequentialGuidTimestampProvider _timestampProvider;

    /// <summary>
    /// Initializes a new instance of the <see cref="SequentialGuidProvider"/> class.
    /// </summary>
    /// <param name="guidInitializer">Supplies the random part, usually <see cref="Guid.NewGuid"/>.</param>
    /// <param name="timestampProvider">Supplies the timestamp, usually <see cref="UniqueSequentialGuidTimestampProvider.GetTimestamp"/>.</param>
    /// <exception cref="ArgumentNullException">If any argument is <see langword="null"/>.</exception>
    public SequentialGuidProvider(SequentialGuidInitializer guidInitializer, SequentialGuidTimestampProvider timestampProvider)
    {
        ArgumentNullException.ThrowIfNull(guidInitializer);
        ArgumentNullException.ThrowIfNull(timestampProvider);

        _initializer = guidInitializer;
        _timestampProvider = timestampProvider;
    }

    /// <inheritdoc />
    /// <exception cref="NotSupportedException">If <paramref name="type"/> is not a defined value.</exception>
    public Guid GetSequentialGuid(SequentialGuidType type = SequentialGuidType.String)
    {
        // Layout of Guid.ToByteArray(): Data1 (4 bytes, little-endian), Data2 (2, LE), Data3 (2, LE), Data4 (8).
        Span<byte> guid = stackalloc byte[16];
        _initializer().TryWriteBytes(guid);

        // The 6 low-order bytes of the big-endian millisecond count.
        Span<byte> timestamp = stackalloc byte[8];
        BinaryPrimitives.WriteInt64BigEndian(timestamp, (_timestampProvider().Ticks - _unixEpochTicks) / TimeSpan.TicksPerMillisecond);
        var milliseconds = timestamp[2..];

        switch (type)
        {
            case SequentialGuidType.String:
                milliseconds.CopyTo(guid);
                // Data1 and Data2 are printed big-endian in the string form.
                guid[..4].Reverse();
                guid[4..6].Reverse();
                break;
            case SequentialGuidType.Binary:
                milliseconds.CopyTo(guid);
                break;
            case SequentialGuidType.Ending:
                milliseconds.CopyTo(guid[10..]);
                break;
            default:
                throw new NotSupportedException($"Not supported sequential GUID type \"{type}\".");
        }

        return new Guid(guid);
    }
}
